using System;using System.Drawing;using System.Drawing.Imaging;using System.IO;using System.Collections.Generic;
namespace MuMuBeans {static class ClockTests {public static void Run(string[] args){List<string> rows=new List<string>();int failed=0;try{using(ClockReader reader=new ClockReader()){double[] expected={37,18,7.97,6.43,49};for(int i=1;i<=5;i++)using(Bitmap full=new Bitmap(args[i]))foreach(double scale in new double[]{1,.75,.5})using(Bitmap resized=new Bitmap(full,new Size((int)(full.Width*scale),(int)(full.Height*scale))))using(Bitmap crop=resized.Clone(ClockReader.Area(resized.Size),PixelFormat.Format32bppArgb)){double? got=reader.Read(crop);bool pass=got.HasValue&&Math.Abs(got.Value-expected[i-1])<.001;rows.Add((pass?"PASS ":"FAIL ")+expected[i-1]+" scale "+scale+" got "+got);if(!pass)failed++;}using(Bitmap empty=new Bitmap(400,180)){bool pass=!reader.Read(empty).HasValue;rows.Add((pass?"PASS":"FAIL")+" empty rejects");if(!pass)failed++;}}
 foreach(double v in new double[]{60,18,7.97})rows.Add("TARGET "+v+" -> "+GameClockWorker.Recovery(v));
 bool logic=GameClockWorker.Recovery(60).Contains("45")&&GameClockWorker.Recovery(18).Contains("3 秒")&&GameClockWorker.Recovery(null).Contains("未确认")&&GameClockWorker.Recovery(78).Contains("未确认")&&GameClockWorker.Recovery(7.97).Contains("不足");if(!logic)failed++;rows.Add((logic?"PASS":"FAIL")+" recovery arithmetic");
 }catch(Exception e){failed++;rows.Add(e.ToString());}using(GameClockWorker worker=new GameClockWorker()) {var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;var type=typeof(GameClockWorker);long now=System.Diagnostics.Stopwatch.GetTimestamp(),freq=System.Diagnostics.Stopwatch.Frequency;lock(type.GetField("gate",flags).GetValue(worker)){type.GetField("value",flags).SetValue(worker,(double?)49);type.GetField("stamp",flags).SetValue(worker,now+freq/10);bool within=worker.RecoveryAt(now).Contains("≈34");type.GetField("stamp",flags).SetValue(worker,now+freq);bool late=worker.RecoveryAt(now).Contains("未确认");type.GetField("stamp",flags).SetValue(worker,now-freq);bool old=worker.RecoveryAt(now).Contains("未确认");bool pass=within&&late&&old;rows.Add((pass?"PASS":"FAIL")+" 补读100ms标近似；拒绝1秒后或过期的读数");if(!pass)failed++;}}
File.WriteAllLines(args[6],rows);Environment.ExitCode=failed==0?0:1;}}}
